/// Pie de la paleta: `"{filtrados} de {total} · {navegación}"`.
/// ES idéntico al formato actual de `command_palette.rs`.
pub fn palette_footer(filtered: usize, total: usize, locale: Locale) -> String {
    match locale {
        Locale::Es | Locale::Pt => format!(
            "{filtered} de {total} · {}",
            t("palette.footer_nav", locale)
        ),
        Locale::It => format!(
            "{filtered} di {total} · {}",
            t("palette.footer_nav", locale)
        ),
        Locale::Fr => format!(
            "{filtered} sur {total} · {}",
            t("palette.footer_nav", locale)
        ),
        Locale::De => format!(
            "{filtered} von {total} · {}",
            t("palette.footer_nav", locale)
        ),
        Locale::En => format!(
            "{filtered} of {total} · {}",
            t("palette.footer_nav", locale)
        ),
    }
}

/// Conteo vivo de la paleta (`"{filtrados} de {total}"`): lo muestra la
/// fila de estado junto a la búsqueda, sin la guía de teclas del pie.
pub fn palette_count(filtered: usize, total: usize, locale: Locale) -> String {
    match locale {
        Locale::Es | Locale::Pt => format!("{filtered} de {total}"),
        Locale::It => format!("{filtered} di {total}"),
        Locale::Fr => format!("{filtered} sur {total}"),
        Locale::De => format!("{filtered} von {total}"),
        Locale::En => format!("{filtered} of {total}"),
    }
}

