    #[test]
    fn no_duplicate_keys() {
        let mut keys: Vec<&str> = MESSAGES.iter().map(|m| m.key).collect();
        keys.sort_unstable();
        let mut i = 1;
        while i < keys.len() {
            assert_ne!(keys[i - 1], keys[i], "clave duplicada: {}", keys[i]);
            i += 1;
        }
    }

