    #[test]
    fn composer_status_keys_resuelven_en_seis_idiomas() {
        // Ola 3: el composer deja de ser solo-ES en el catálogo (el cableado
        // del locale al composer es P2; las claves ya resuelven en 6 idiomas).
        for key in ["assistant.composer_pending", "assistant.composer_empty"] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
            }
        }
        assert_eq!(
            super::t("assistant.composer_empty", Locale::Es),
            "Escribí algo para activar Enviar."
        );
    }

    #[test]
    fn dictate_keys_resuelven_en_seis_idiomas() {
        // STT: el mic del composer habla los 6 idiomas (tooltip, estado
        // grabando y hover honesto con comandos).
        for key in [
            "assistant.composer.dictate",
            "assistant.composer.dictate_stop",
            "assistant.composer.dictate_recording",
            "assistant.composer.dictate_missing",
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
            }
        }
        assert_eq!(
            super::t("assistant.composer.dictate", Locale::Es),
            "Dictar por voz"
        );
        // Hover honesto: comando instalable + ruta esperada del modelo +
        // override por env, en los 6 idiomas (sin placeholders: ruta `~`
        // estable; el toast de la app trae la ruta dinámica exacta).
        for locale in [
            Locale::Es,
            Locale::En,
            Locale::Pt,
            Locale::It,
            Locale::Fr,
            Locale::De,
        ] {
            let missing = super::t("assistant.composer.dictate_missing", locale);
            assert!(missing.contains("sudo pacman -S whisper-cpp"), "{missing}");
            assert!(missing.contains("ggml-base.bin"), "{missing}");
            assert!(missing.contains("GRAFITO_WHISPER_MODEL"), "{missing}");
        }
    }

