    #[test]
    fn algebra_b_a143_templates_conservan_placeholders_en_seis_idiomas() {
        // B-A143: los 10 templates `summary_*` conservan sus placeholders en
        // los 6 idiomas (`{n}/{perim}/{area}/{len}/{bins}/{x}/{y}`) y
        // `algebra_msg` los expone por sufijo. Notación intacta: `L=/P=/A=`,
        // `BarChart/PieChart`, `bins`, `=` y `·`.
        for (suffix, placeholders) in [
            ("summary_points", ["{n}", "", ""]),
            ("summary_vertices", ["{n}", "", ""]),
            ("summary_vertices_full", ["{n}", "{perim}", "{area}"]),
            ("summary_polyline", ["{n}", "{len}", ""]),
            ("summary_locus", ["{n}", "", ""]),
            ("summary_data", ["{n}", "", ""]),
            ("summary_histogram", ["{n}", "{bins}", ""]),
            ("summary_barchart", ["{n}", "", ""]),
            ("summary_pie_data", ["{n}", "", ""]),
            ("summary_table", ["{n}", "{x}", "{y}"]),
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::algebra_msg(suffix, locale);
                for ph in placeholders {
                    if ph.is_empty() {
                        continue;
                    }
                    assert!(text.contains(ph), "{suffix} sin {ph} en {locale:?}: {text}");
                }
            }
        }
        assert_eq!(
            super::t("algebra.summary_vertices_full", Locale::En),
            "{n} vertices  P={perim}  A={area}"
        );
        assert_eq!(
            super::t("algebra.summary_histogram", Locale::De),
            "{n} Daten · {bins} Bins"
        );
    }

    #[test]
    fn algebra_b_a144_templates_conservan_placeholders_en_seis_idiomas() {
        // B-A144: los 4 templates (`poly_projected_4d/nd`, `cone_infinite`,
        // `cylinder_infinite`) conservan sus placeholders en los 6 idiomas y
        // `algebra_msg` expone los 13 sufijos. Notación intacta: `4D/{}D`,
        // `θ`/`°`, `(clip ±50)`, `→`, `=`.
        for (suffix, placeholders) in [
            ("poly_projected_4d", ["{name}", "{scale}", ""]),
            ("poly_projected_nd", ["{family}", "{dim}", "{scale}"]),
            ("cone_infinite", ["{x}", "{deg}", ""]),
            ("cylinder_infinite", ["{r}", "{x}", ""]),
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::algebra_msg(suffix, locale);
                for ph in placeholders {
                    if ph.is_empty() {
                        continue;
                    }
                    assert!(text.contains(ph), "{suffix} sin {ph} en {locale:?}: {text}");
                }
            }
        }
        // Kinds y familias no son templates: resuelven sin placeholders.
        for suffix in [
            "poly_kind_pentachoron",
            "poly_family_simplex",
            "poly_family_cross",
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::algebra_msg(suffix, locale);
                assert!(
                    !text.contains('{'),
                    "{suffix} con placeholder en {locale:?}: {text}"
                );
            }
        }
        assert_eq!(
            super::t("algebra.poly_projected_nd", Locale::En),
            "{family} {dim}D centered and projected · scale={scale}"
        );
        assert_eq!(
            super::t("algebra.cone_infinite", Locale::De),
            "Apex=({x},{y},{z}) θ={deg}° (clip ±50)"
        );
    }

