    #[test]
    fn anim_export_errors_resuelven_en_seis_idiomas() {
        // B-A64: los 4 templates de error de validación resuelven en los 6
        // idiomas, sin vacíos ni fallback a la clave (overlay total PT/IT/FR/DE
        // + ES/EN). Las unidades fps/bitrate/frames no se traducen; los
        // placeholders se conservan en los 6 idiomas.
        for key in [
            "anim.export_err_fps",
            "anim.export_err_bitrate",
            "anim.export_err_frames_longform",
            "anim.export_err_frames_ram",
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
            }
        }
        // ES pineado a los literales canónicos previos de `validate_selection`
        // / `aviso_limite` (`assistant.rs:1453-1464,:1495-1502`): el display
        // localizado conserva el copy canónico en español.
        assert_eq!(
            super::t("anim.export_err_fps", Locale::Es),
            "fps {n} fuera de {min}..={max}"
        );
        assert_eq!(
            super::t("anim.export_err_bitrate", Locale::Es),
            "bitrate {n} fuera de {min}..={max}"
        );
        assert_eq!(
            super::t("anim.export_err_frames_longform", Locale::Es),
            "frames {n} fuera de 1..={tope} (50 s a 30 fps): partí el video en dos"
        );
        assert_eq!(
            super::t("anim.export_err_frames_ram", Locale::Es),
            "frames {n} fuera de 1..={tope} (todo en RAM): exportá a mp4 para long-form (hasta {max}) o bajá los frames"
        );
        // Placeholders conservados en los 6 idiomas.
        for locale in [
            Locale::Es,
            Locale::En,
            Locale::Pt,
            Locale::It,
            Locale::Fr,
            Locale::De,
        ] {
            let fps = super::t("anim.export_err_fps", locale);
            assert!(fps.contains("{n}"), "sin {{n}} fps en {locale:?}");
            assert!(fps.contains("{min}"), "sin {{min}} fps en {locale:?}");
            assert!(fps.contains("{max}"), "sin {{max}} fps en {locale:?}");
            let bitrate = super::t("anim.export_err_bitrate", locale);
            assert!(bitrate.contains("{n}"), "sin {{n}} bitrate en {locale:?}");
            let largo = super::t("anim.export_err_frames_longform", locale);
            assert!(largo.contains("{n}"), "sin {{n}} longform en {locale:?}");
            assert!(
                largo.contains("{tope}"),
                "sin {{tope}} longform en {locale:?}"
            );
            let ram = super::t("anim.export_err_frames_ram", locale);
            assert!(ram.contains("{n}"), "sin {{n}} ram en {locale:?}");
            assert!(ram.contains("{tope}"), "sin {{tope}} ram en {locale:?}");
            assert!(ram.contains("{max}"), "sin {{max}} ram en {locale:?}");
        }
        assert_eq!(
            anim_msg("export_err_fps", Locale::En),
            "fps {n} out of {min}..={max}"
        );
        assert_eq!(
            anim_msg("export_err_frames_longform", Locale::Fr),
            "frames {n} hors de 1..={tope} (50 s à 30 fps) : divisez la vidéo en deux"
        );
        assert_eq!(
            anim_msg("export_err_frames_ram", Locale::De),
            "frames {n} außerhalb 1..={tope} (alles in RAM): exportiere als mp4 für long-form (bis {max}) oder reduziere die Frames"
        );
    }

