    #[test]
    fn b_a101_turno_propuesta_resuelve_en_seis_idiomas() {
        // B-A101: las 22 `assistant.auth.*/clarify.*/plan.*/turn.*/apply.*`
        // del chrome turno/propuesta resuelven en los 6 idiomas, sin vacíos
        // ni fallback a la clave (overlay total PT/IT/FR/DE + ES/EN). ES
        // pineado a los literales previos de `assistant.rs` (:11746, :11800,
        // :11805, :11864-11865, :11889, :11916, :12970, :12981, :13199,
        // :13481, :13488-13489, :13518, :13554-13555, :13563, :13585, :13639,
        // :13750, :13934, :14084). El "Cancelando…" del composer (:12487)
        // reutiliza `assistant.pending.cancelling` existente (pin aparte).
        use super::Locale;
        for key in [
            "assistant.auth.local_unresolved",
            "assistant.auth.authorize_remote",
            "assistant.auth.stay_local",
            "assistant.clarify.answer_in_chat",
            "assistant.clarify.dismiss_hint",
            "assistant.plan.local_checked",
            "assistant.apply.apply_in_grafito",
            "assistant.turn.you",
            "assistant.turn.query_tag",
            "assistant.turn.task_state",
            "assistant.apply.rejected_label",
            "assistant.apply.show",
            "assistant.apply.reshow_hint",
            "assistant.apply.apply",
            "assistant.apply.reject",
            "assistant.apply.hide_hint",
            "assistant.apply.detail",
            "assistant.apply.edit_in_input",
            "assistant.apply.applied",
            "assistant.apply.summarized_applied",
            "assistant.apply.applied_to_grafito",
            "assistant.apply.ready",
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
                assert!(
                    !text.contains("assistant."),
                    "fallback en {locale:?}: {text}"
                );
            }
        }
        assert_eq!(
            super::t("assistant.auth.local_unresolved", Locale::Es),
            "Consulta local sin resolver"
        );
        assert_eq!(
            super::t("assistant.auth.authorize_remote", Locale::Es),
            "Autorizar consulta remota"
        );
        assert_eq!(
            super::t("assistant.auth.stay_local", Locale::Es),
            "Seguir localmente"
        );
        assert_eq!(
            super::t("assistant.clarify.answer_in_chat", Locale::Es),
            "Responder en el chat"
        );
        assert_eq!(
            super::t("assistant.clarify.dismiss_hint", Locale::Es),
            "Descartar y escribir la respuesta a mano"
        );
        assert_eq!(
            super::t("assistant.plan.local_checked", Locale::Es),
            "Propuesta local comprobada"
        );
        assert_eq!(
            super::t("assistant.apply.apply_in_grafito", Locale::Es),
            "Aplicar en Grafito"
        );
        assert_eq!(super::t("assistant.turn.you", Locale::Es), "Vos");
        assert_eq!(super::t("assistant.turn.query_tag", Locale::Es), "consulta");
        assert_eq!(
            super::t("assistant.turn.task_state", Locale::Es),
            "Estado de la tarea"
        );
        assert_eq!(
            super::t("assistant.apply.rejected_label", Locale::Es),
            "Propuesta rechazada."
        );
        assert_eq!(super::t("assistant.apply.show", Locale::Es), "Mostrar");
        assert_eq!(
            super::t("assistant.apply.reshow_hint", Locale::Es),
            "Volver a mostrar la propuesta"
        );
        assert_eq!(super::t("assistant.apply.apply", Locale::Es), "Aplicar");
        assert_eq!(super::t("assistant.apply.reject", Locale::Es), "Rechazar");
        assert_eq!(
            super::t("assistant.apply.hide_hint", Locale::Es),
            "Ocultar esta propuesta"
        );
        assert_eq!(
            super::t("assistant.apply.detail", Locale::Es),
            "Detalle · propuesta {n}"
        );
        assert_eq!(
            super::t("assistant.apply.edit_in_input", Locale::Es),
            "Editar en la entrada"
        );
        assert_eq!(super::t("assistant.apply.applied", Locale::Es), "Aplicada");
        assert_eq!(
            super::t("assistant.apply.summarized_applied", Locale::Es),
            "Propuesta aplicada de una respuesta resumida"
        );
        assert_eq!(
            super::t("assistant.apply.applied_to_grafito", Locale::Es),
            "Aplicada a Grafito"
        );
        assert_eq!(
            super::t("assistant.apply.ready", Locale::Es),
            "Lista para aplicar"
        );
        // EN pineado (el resto de idiomas lo cubre el loop sin-vacío de arriba
        // + los overlays totales PT/IT/FR/DE).
        assert_eq!(
            super::t("assistant.auth.local_unresolved", Locale::En),
            "Unresolved local query"
        );
        assert_eq!(
            super::t("assistant.apply.detail", Locale::En),
            "Detail · proposal {n}"
        );
        assert_eq!(
            super::t("assistant.apply.ready", Locale::De),
            "Bereit zum Anwenden"
        );
        assert_eq!(super::t("assistant.turn.you", Locale::Fr), "Vous");
        // El template conserva su placeholder en los 6 idiomas.
        for locale in [
            Locale::Es,
            Locale::En,
            Locale::Pt,
            Locale::It,
            Locale::Fr,
            Locale::De,
        ] {
            assert!(
                super::t("assistant.apply.detail", locale).contains("{n}"),
                "template sin {{n}} en {locale:?}"
            );
        }
    }

