    #[test]
    fn export_toasts_resuelven_en_seis_idiomas() {
        // B-A171: las 3 `export.*` toasts de copiado resuelven en los 6
        // idiomas, sin vacíos ni fallback a la clave (overlay total
        // PT/IT/FR/DE + ES/EN). ES pineado a los literales previos de
        // `sheet_layout.rs:4110-4123` (`export_svg_copied_text`/
        // `export_svg_error_text`/`export_clipboard_copied_text`).
        // Templates `{bytes}`/`{error}`/`{label}`. Labels `MathML`/
        // `TikZ-eje`/`HTML` identificadores intactos (precedente B-A169).
        for key in [
            "export.svg_copied",
            "export.svg_error",
            "export.clipboard_copied",
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
                assert!(
                    !text.contains("export."),
                    "{key} con fallback visible en {locale:?}: {text}"
                );
            }
        }
        assert_eq!(
            super::t("export.svg_copied", Locale::Es),
            "SVG copiado al portapapeles ({bytes} bytes)"
        );
        assert_eq!(
            super::t("export.svg_error", Locale::Es),
            "No se pudo copiar SVG: {error}"
        );
        assert_eq!(
            super::t("export.clipboard_copied", Locale::Es),
            "{label} copiado al portapapeles ({bytes} bytes)"
        );
        assert_eq!(
            super::t("export.svg_copied", Locale::En),
            "SVG copied to the clipboard ({bytes} bytes)"
        );
        assert_eq!(
            super::t("export.svg_error", Locale::Pt),
            "Não foi possível copiar o SVG: {error}"
        );
        assert_eq!(
            super::t("export.clipboard_copied", Locale::It),
            "{label} copiato negli appunti ({bytes} byte)"
        );
        assert_eq!(
            super::t("export.svg_copied", Locale::Fr),
            "SVG copié dans le presse-papiers ({bytes} octets)"
        );
        assert_eq!(
            super::t("export.svg_error", Locale::De),
            "SVG konnte nicht kopiert werden: {error}"
        );
        for locale in [
            Locale::Es,
            Locale::En,
            Locale::Pt,
            Locale::It,
            Locale::Fr,
            Locale::De,
        ] {
            let copied = super::t("export.svg_copied", locale);
            assert!(
                copied.contains("{bytes}"),
                "svg_copied sin {{bytes}} en {locale:?}"
            );
            let failed = super::t("export.svg_error", locale);
            assert!(
                failed.contains("{error}"),
                "svg_error sin {{error}} en {locale:?}"
            );
            let generic = super::t("export.clipboard_copied", locale);
            assert!(
                generic.contains("{label}"),
                "clipboard_copied sin {{label}} en {locale:?}"
            );
            assert!(
                generic.contains("{bytes}"),
                "clipboard_copied sin {{bytes}} en {locale:?}"
            );
        }
        assert_eq!(
            export_msg("svg_copied", Locale::Es),
            "SVG copiado al portapapeles ({bytes} bytes)"
        );
        assert_eq!(
            export_msg("svg_error", Locale::De),
            "SVG konnte nicht kopiert werden: {error}"
        );
        assert_eq!(
            export_msg("clipboard_copied", Locale::Pt),
            "{label} copiado para a área de transferência ({bytes} bytes)"
        );
        assert_eq!(export_msg("nope", Locale::Es), "nope");
        assert_eq!(EXPORT_KEYS.len(), 25);
    }

