    #[test]
    fn picker_keys_resuelven_en_seis_idiomas() {
        // B-A117: las 8 `picker.*` (chrome vivo del color picker + diálogo)
        // resuelven en los 6 idiomas, sin vacíos ni fallback a la clave
        // (overlay total PT/IT/FR/DE + ES/EN). ES pineado a los literales
        // previos de `color_picker.rs` (`:123` wheel, `:229` Brillo, `:238`
        // a11y, `:444` Favoritos, `:468` fav {n}) y de `app/ui.rs`
        // (título + hint del diálogo).
        for key in [
            "picker.wheel_a11y",
            "picker.brightness_label",
            "picker.brightness_a11y",
            "picker.favorites_label",
            "picker.fav_a11y",
            "picker.fav_tooltip",
            "picker.dialog_title",
            "picker.dialog_hint",
        ] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
            }
        }
        assert_eq!(
            super::t("picker.wheel_a11y", Locale::Es),
            "Tono y saturación"
        );
        assert_eq!(super::t("picker.brightness_label", Locale::Es), "Brillo");
        assert_eq!(
            super::t("picker.dialog_title", Locale::Es),
            "Selector de Color"
        );
        assert_eq!(
            super::t("picker.dialog_hint", Locale::Pt),
            "As mudanças aplicam-se na hora"
        );
        assert_eq!(
            super::t("picker.fav_tooltip", Locale::It),
            "Clic: applica\nClic destro: salva\nRGB: ({r}, {g}, {b})"
        );
        assert_eq!(
            super::t("picker.fav_a11y", Locale::Fr),
            "Couleur favorite {n}"
        );
        assert_eq!(
            super::t("picker.brightness_a11y", Locale::De),
            "Farbhelligkeit"
        );
        assert_eq!(picker_msg("wheel_a11y", Locale::Es), "Tono y saturación");
        assert_eq!(
            picker_msg("dialog_hint", Locale::De),
            "Änderungen werden sofort übernommen"
        );
        assert_eq!(picker_msg("nope", Locale::Es), "nope");
        assert_eq!(PICKER_KEYS.len(), 8);
    }

