    #[test]
    fn stats_b_a164_goto_resuelve_en_seis_idiomas() {
        // B-A164: goto de la hoja (2 `stats.sheet_goto_*`) resuelve en los
        // 6 idiomas, sin vacíos ni fallback a la clave (overlay total
        // PT/IT/FR/DE + ES/EN). ES pineado a los literales previos de
        // `spreadsheet.rs:152` (hint) + `:168` (botón). Concat a propósito
        // para que el blindaje por `include_str!` no se auto-matchee con
        // este test (precedente B-A155/B-A156/B-A157/B-A163).
        for key in ["stats.sheet_goto_hint", "stats.sheet_goto_go"] {
            for locale in [
                Locale::Es,
                Locale::En,
                Locale::Pt,
                Locale::It,
                Locale::Fr,
                Locale::De,
            ] {
                let text = super::t(key, locale);
                assert!(!text.is_empty(), "{key} vacío en {locale:?}");
                assert_ne!(text, key, "{key} sin resolver en {locale:?}");
                assert!(!text.contains("stats."), "fallback en {locale:?}: {text}");
            }
        }
        assert_eq!(
            super::t("stats.sheet_goto_hint", Locale::Es),
            ["Ir a celda ", "(C3)"].concat()
        );
        assert_eq!(super::t("stats.sheet_goto_go", Locale::Es), "Ir");
        assert_eq!(
            super::t("stats.sheet_goto_hint", Locale::En),
            "Go to cell (C3)"
        );
        assert_eq!(
            super::t("stats.sheet_goto_hint", Locale::Pt),
            "Ir para célula (C3)"
        );
        assert_eq!(
            super::t("stats.sheet_goto_hint", Locale::It),
            "Vai alla cella (C3)"
        );
        assert_eq!(
            super::t("stats.sheet_goto_hint", Locale::Fr),
            "Aller à la cellule (C3)"
        );
        assert_eq!(
            super::t("stats.sheet_goto_hint", Locale::De),
            "Zu Zelle gehen (C3)"
        );
        assert_eq!(stats_msg("sheet_goto_hint", Locale::Es), "Ir a celda (C3)");
        assert_eq!(stats_msg("sheet_goto_go", Locale::De), "Los");
    }

