    #[test]
    fn stats_b_a167_chip_hint_resuelve_en_seis_idiomas() {
        // B-A167: hover del chip de la hoja (`stats.sheet_chip_hint` con
        // template `{ventana}`) resuelve en los 6 idiomas, sin vacíos ni
        // fallback a la clave (overlay total PT/IT/FR/DE + ES/EN). ES
        // pineado al literal previo de `spreadsheet.rs:109-112`. Concat a
        // propósito para que el blindaje por `include_str!` no se
        // auto-matchee con este test (precedente B-A164/B-A166).
        for locale in [
            Locale::Es,
            Locale::En,
            Locale::Pt,
            Locale::It,
            Locale::Fr,
            Locale::De,
        ] {
            let template = super::t("stats.sheet_chip_hint", locale);
            assert!(!template.is_empty(), "vacío en {locale:?}");
            assert_ne!(
                template, "stats.sheet_chip_hint",
                "sin resolver en {locale:?}"
            );
            assert!(
                template.contains("{ventana}"),
                "sin {{ventana}} en {locale:?}"
            );
            assert!(
                !template.contains("stats."),
                "fallback en {locale:?}: {template}"
            );
        }
        assert_eq!(
            super::t("stats.sheet_chip_hint", Locale::Es),
            [
                "Celda en edición (accent) o esquina visible de la hoja 400×400. ",
                "Ventana {ventana} · 10 000 celdas vivas."
            ]
            .concat()
        );
        assert_eq!(
            super::t("stats.sheet_chip_hint", Locale::En),
            [
                "Cell being edited (accent) or visible corner of the 400×400 sheet. ",
                "Window {ventana} · 10,000 live cells."
            ]
            .concat()
        );
        assert_eq!(
            super::t("stats.sheet_chip_hint", Locale::Pt),
            "Célula em edição (accent) ou canto visível da folha 400×400. Janela {ventana} · 10 000 células vivas."
        );
        assert_eq!(
            super::t("stats.sheet_chip_hint", Locale::It),
            "Cella in modifica (accent) o angolo visibile del foglio 400×400. Finestra {ventana} · 10 000 celle attive."
        );
        assert_eq!(
            super::t("stats.sheet_chip_hint", Locale::Fr),
            "Cellule en cours d'édition (accent) ou coin visible de la feuille 400×400. Fenêtre {ventana} · 10 000 cellules actives."
        );
        assert_eq!(
            super::t("stats.sheet_chip_hint", Locale::De),
            "Zelle in Bearbeitung (accent) oder sichtbare Ecke des 400×400-Blatts. Fenster {ventana} · 10.000 aktive Zellen."
        );
        assert_eq!(
            stats_msg("sheet_chip_hint", Locale::Es),
            [
                "Celda en edición (accent) o esquina visible de la hoja 400×400. ",
                "Ventana {ventana} · 10 000 celdas vivas."
            ]
            .concat()
        );
    }

