        assert_eq!(super::t("teach.exercise_retry", Locale::Es), "Reintentar");
        assert_eq!(
            super::t("teach.exercise_other", Locale::Es),
            "Otro ejercicio"
        );
        assert_eq!(
            super::t("teach.exercise_header", Locale::Es),
            "Ejercicio · {tema}"
        );
        assert_eq!(
            super::t("teach.overlay_title", Locale::Es),
            "Enseñanza — Paso a paso"
        );
