        assert_eq!(super::t("orb.shaping", Locale::Es), "Preparando respuesta");
        assert_eq!(super::t("orb.shaping", Locale::En), "Preparing response");
        assert_eq!(super::t("orb.cancelling", Locale::Es), "Cancelando");
